(4885787, 709310, 26001, '<td valign="top">magnificent! one of my favourites in the challenge. 10</td>', 'magnificent! one of my favourites in the challenge. 10', '2008-08-13 13:06:25.000000', NULL, 1),
(4885791, 710200, 26001, '<td valign="top">simplicity at its best 9<br/>this brilliantly shows how basic photography rules of thirds/exposure/dof/lighting/colors could make an excellent photo without any frills.</td>', 'simplicity at its best 9this brilliantly shows how basic photography rules of thirds/exposure/dof/lighting/colors could make an excellent photo without any frills.', '2008-08-13 13:10:19.000000', NULL, 1),
(4885796, 710176, 26001, '<td valign="top">absolutely cool!!! taking off only one point for not having enough details on ducks but still a very strong 9</td>', 'absolutely cool!!! taking off only one point for not having enough details on ducks but still a very strong 9', '2008-08-13 13:14:22.000000', NULL, 1),
(4885806, 710269, 26001, '<td valign="top">cool concept. love the lighting. 9</td>', 'cool concept. love the lighting. 9', '2008-08-13 13:18:09.000000', NULL, 1),
(4885811, 710209, 96721, '<td valign="top">Nice shot - The yellow in the border doesn''t work for me though</td>', 'Nice shot - The yellow in the border doesn''t work for me though', '2008-08-13 13:23:53.000000', NULL, 1),
(4885824, 710101, 32872, '<td valign="top">Brilliant!</td>', 'Brilliant!', '2008-08-13 13:29:12.000000', NULL, 1),
(4885825, 708950, 96721, '<td valign="top">Looks out of focus and the White balance also seems very off giving the orange cast to the whole picture</td>', 'Looks out of focus and the White balance also seems very off giving the orange cast to the whole picture', '2008-08-13 13:29:19.000000', NULL, 1),
(4885827, 710210, 32872, '<td valign="top">wow!!</td>', 'wow!!', '2008-08-13 13:30:14.000000', NULL, 1),
(4885830, 709911, 96721, '<td valign="top">Lovely DOF and nice idea hope your camera is not too wet :)<br/> <br/>I might have been tempted to do a tighter crop and lose the dark area at the bottom as it seems a little distracting to my eye.</td>', 'Lovely DOF and nice idea hope your camera is not too wet :) I might have been tempted to do a tighter crop and lose the dark area at the bottom as it seems a little distracting to my eye.', '2008-08-13 13:31:33.000000', NULL, 1),
(4885835, 710031, 96721, '<td valign="top">Nice capture: A real pity the duck was the female as IMHO a brightly coloured male would have really added to the image.</td>', 'Nice capture: A real pity the duck was the female as IMHO a brightly coloured male would have really added to the image.', '2008-08-13 13:35:02.000000', NULL, 1),
(4885839, 710289, 96721, '<td valign="top">I would have liked to see greater DOF here the flowers? in the foreground seem very dstracting</td>', 'I would have liked to see greater DOF here the flowers? in the foreground seem very dstracting', '2008-08-13 13:37:16.000000', NULL, 1),
(4885843, 710248, 95240, '<td valign="top">You picked the perfect scene for this ducks expression. I think I would like just a tiny bit more light on the duck, but this is my favorite of the challenge</td>', 'You picked the perfect scene for this ducks expression. I think I would like just a tiny bit more light on the duck, but this is my favorite of the challenge', '2008-08-13 13:39:28.000000', NULL, 1),
(4885849, 710101, 96721, '<td valign="top">Great shot :)<br/> <br/>Almost reminds me of the Shawshank Redemption cover, only a small point but I think maybe there is too much foreground for my taste.</td>', 'Great shot :) Almost reminds me of the Shawshank Redemption cover, only a small point but I think maybe there is too much foreground for my taste.', '2008-08-13 13:41:34.000000', NULL, 1),
(4885856, 710040, 96721, '<td valign="top">Nice Detail, lighting and execution - Composition wise my eyes are drawn away from the duck a little too much and that green neon light is really distracting.</td>', 'Nice Detail, lighting and execution - Composition wise my eyes are drawn away from the duck a little too much and that green neon light is really distracting.', '2008-08-13 13:45:15.000000', NULL, 1),
(4885861, 709314, 96721, '<td valign="top">Nice lighting, I really like the idea and the way the models lines are almost mirrored is really pleasing to the eye.</td>', 'Nice lighting, I really like the idea and the way the models lines are almost mirrored is really pleasing to the eye.', '2008-08-13 13:50:37.000000', NULL, 1),
(4885867, 710038, 96721, '<td valign="top">Nice original idea, I marked you down one point for composition though as I feel cutting off the ducks but leaving so much space at the top was a bit of a mistake.</td>', 'Nice original idea, I marked you down one point for composition though as I feel cutting off the ducks but leaving so much space at the top was a bit of a mistake.', '2008-08-13 13:53:34.000000', NULL, 1),
(4885870, 707755, 96721, '<td valign="top">Focus looks a little soft to me?</td>', 'Focus looks a little soft to me?', '2008-08-13 13:55:12.000000', NULL, 1),
(4885875, 709310, 96721, '<td valign="top">Really dramatic one of my favorites in this challenge.</td>', 'Really dramatic one of my favorites in this challenge.', '2008-08-13 13:56:57.000000', NULL, 1),
(4885879, 708528, 96721, '<td valign="top">I think it would have worked better with the focus being on the duck and not on your middle finger, maybe just personal taste though.</td>', 'I think it would have worked better with the focus being on the duck and not on your middle finger, maybe just personal taste though.', '2008-08-13 13:58:27.000000', NULL, 1),
(4885892, 710250, 47791, '<td valign="top">The light is too bright. Good colours used though and the net makes a clever background.</td>', 'The light is too bright. Good colours used though and the net makes a clever background.', '2008-08-13 14:00:47.000000', NULL, 1),
(4885893, 710071, 47791, '<td valign="top">Too bright at the edges.</td>', 'Too bright at the edges.', '2008-08-13 14:01:15.000000', NULL, 1),
(4885896, 710237, 47791, '<td valign="top">Nice shot. <br/>Good colours and dof.</td>', 'Nice shot. Good colours and dof.', '2008-08-13 14:01:55.000000', NULL, 1),
(4885898, 709588, 47791, '<td valign="top">Good idea but let down by lighting.</td>', 'Good idea but let down by lighting.', '2008-08-13 14:02:23.000000', NULL, 1),
(4885902, 708875, 47791, '<td valign="top">Lots of movement. Really grabs the attention.</td>', 'Lots of movement. Really grabs the attention.', '2008-08-13 14:02:54.000000', NULL, 1),
(4885907, 710203, 47791, '<td valign="top">Very nice. Strong colours and good DOF.</td>', 'Very nice. Strong colours and good DOF.', '2008-08-13 14:04:01.000000', NULL, 1),
