(4885925, 710176, 47791, '<td valign="top">Very funny but I think you''ve lost something in using the glass as a backdrop. The zombie ducks dont really pop out at you... Now theres a sentence I never thought Id type.</td>', 'Very funny but I think you''ve lost something in using the glass as a backdrop. The zombie ducks dont really pop out at you... Now theres a sentence I never thought Id type.', '2008-08-13 14:10:54.000000', NULL, 1),
(4885926, 710064, 47791, '<td valign="top">Getting closer to the ducks might have improved this but overall its a really good image.</td>', 'Getting closer to the ducks might have improved this but overall its a really good image.', '2008-08-13 14:11:47.000000', NULL, 1),
(4885928, 710075, 47791, '<td valign="top">Good composition. Good colours. Good dof.</td>', 'Good composition. Good colours. Good dof.', '2008-08-13 14:12:22.000000', NULL, 1),
