INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4886454, 710033, 65083, '<td valign="top">nice</td>', 'nice', '2008-08-13 16:53:14.000000', NULL, 1),
(4886459, 710180, 65083, '<td valign="top">not sure the b/w is working for this picture</td>', 'not sure the b/w is working for this picture', '2008-08-13 16:54:02.000000', NULL, 1),
(4886473, 709496, 58457, '<td valign="top">i don''t know if it is your lighting or processing, but it seems a bit harsh.  the duck and the left side of the bent sock are a bit tough to look at...  concept is good though... plus you have a hole in the toe of the other sock.</td>', 'i don''t know if it is your lighting or processing, but it seems a bit harsh.  the duck and the left side of the bent sock are a bit tough to look at...  concept is good though... plus you have a hole in the toe of the other sock.', '2008-08-13 17:03:16.000000', NULL, 1),
(4886474, 709141, 58457, '<td valign="top">well that is just ridiculous.  frick.  i gotta learn how to do that.  unreal.</td>', 'well that is just ridiculous.  frick.  i gotta learn how to do that.  unreal.', '2008-08-13 17:04:05.000000', NULL, 1),
(4886482, 710202, 58457, '<td valign="top">I don''t think your concept is pushed quite far enough... i''d like to see a little more tension somehow--maybe a more dramatic angle?  not sure...  however, i love the contrasting colors of the duck in the foreground and the brooding clouds in the distance.</td>', 'I don''t think your concept is pushed quite far enough... i''d like to see a little more tension somehow--maybe a more dramatic angle?  not sure...  however, i love the contrasting colors of the duck in the foreground and the brooding clouds in the distance.', '2008-08-13 17:05:46.000000', NULL, 1),
(4886485, 710248, 58457, '<td valign="top">pretty cool pan shot.</td>', 'pretty cool pan shot.', '2008-08-13 17:06:17.000000', NULL, 1),
(4886490, 710037, 58457, '<td valign="top">this could be framed in a baby''s room.  simple, but a solid effort.</td>', 'this could be framed in a baby''s room.  simple, but a solid effort.', '2008-08-13 17:07:18.000000', NULL, 1),
(4886491, 707547, 58457, '<td valign="top">cute</td>', 'cute', '2008-08-13 17:07:34.000000', NULL, 1),
(4886498, 709503, 58457, '<td valign="top">conceptually very cool... technique and composition leave a bit to be desired.  I think the music should have taken up the whole frame... more like a sea that way (which i understand is tough w/o a larger printer...)  hmmm...  maybe a bit more light would''ve helped too.</td>', 'conceptually very cool... technique and composition leave a bit to be desired.  I think the music should have taken up the whole frame... more like a sea that way (which i understand is tough w/o a larger printer...)  hmmm...  maybe a bit more light would''ve helped too.', '2008-08-13 17:09:43.000000', NULL, 1),
(4886501, 708528, 58457, '<td valign="top">is that Ted Lilly?</td>', 'is that Ted Lilly?', '2008-08-13 17:10:54.000000', NULL, 1),
(4886503, 708905, 58457, '<td valign="top">good luck!</td>', 'good luck!', '2008-08-13 17:11:25.000000', NULL, 1),
(4886507, 708613, 58457, '<td valign="top">hmmmm... <i>Actual </i>ducks... I wonder how you will fare.</td>', 'hmmmm... Actual ducks... I wonder how you will fare.', '2008-08-13 17:11:53.000000', NULL, 1),
(4886509, 709505, 58457, '<td valign="top">solid entry.  nice frozen splash and the duck contrasts the water and sky well.</td>', 'solid entry.  nice frozen splash and the duck contrasts the water and sky well.', '2008-08-13 17:12:32.000000', NULL, 1),
(4886511, 710200, 58457, '<td valign="top">i think you should''ve put a thin black line around your image when going w/ that huge white border.  you lost the bottom left corner--kinda trails into nothingness.</td>', 'i think you should''ve put a thin black line around your image when going w/ that huge white border.  you lost the bottom left corner--kinda trails into nothingness.', '2008-08-13 17:13:53.000000', NULL, 1),
(4886518, 709310, 58457, '<td valign="top">I could just see the Terminator''s big metal foot come smashing down on this.</td>', 'I could just see the Terminator''s big metal foot come smashing down on this.', '2008-08-13 17:17:04.000000', NULL, 1),
(4886524, 710068, 58457, '<td valign="top">good luck!</td>', 'good luck!', '2008-08-13 17:18:28.000000', NULL, 1),
(4886525, 710097, 58457, '<td valign="top">good luck!</td>', 'good luck!', '2008-08-13 17:19:03.000000', NULL, 1),
(4886526, 709141, 29777, '<td valign="top">killer, how did you do it?</td>', 'killer, how did you do it?', '2008-08-13 17:19:09.000000', NULL, 1),
(4886530, 709865, 29777, '<td valign="top">i like the even, consistent lighting and shadow.</td>', 'i like the even, consistent lighting and shadow.', '2008-08-13 17:22:06.000000', NULL, 1),
(4886533, 710037, 29777, '<td valign="top">like the lighting</td>', 'like the lighting', '2008-08-13 17:22:37.000000', NULL, 1),
(4886538, 710057, 96614, '<td valign="top">Nice shot! Next time try a slightly faster shutter speed</td>', 'Nice shot! Next time try a slightly faster shutter speed', '2008-08-13 17:25:56.000000', NULL, 1),
(4886539, 710207, 29777, '<td valign="top">good focus on the eyes. too bad the duck does not fit well into the floaty. Lighting is too harsh and direct.</td>', 'good focus on the eyes. too bad the duck does not fit well into the floaty. Lighting is too harsh and direct.', '2008-08-13 17:26:14.000000', NULL, 1),
(4886543, 709755, 29777, '<td valign="top">The point of the composition is lost. There is no clear direction to the image. The eyes move in a circle around it and to the middle and then around again. Also, there are lots of shadows.</td>', 'The point of the composition is lost. There is no clear direction to the image. The eyes move in a circle around it and to the middle and then around again. Also, there are lots of shadows.', '2008-08-13 17:27:59.000000', NULL, 1),
(4886545, 710179, 29777, '<td valign="top">lighting is harsh without creating a mood. A bit too much like a random snapshot. Focus on the duck is soft.</td>', 'lighting is harsh without creating a mood. A bit too much like a random snapshot. Focus on the duck is soft.', '2008-08-13 17:29:32.000000', NULL, 1),
(4886546, 710077, 29777, '<td valign="top">clever idea</td>', 'clever idea', '2008-08-13 17:30:00.000000', NULL, 1),
(4886552, 710129, 29777, '<td valign="top">love the color treatment on this. too bad the chest is "washed out." I could not help the pun.</td>', 'love the color treatment on this. too bad the chest is "washed out." I could not help the pun.', '2008-08-13 17:33:42.000000', NULL, 1),
(4886554, 709818, 29777, '<td valign="top">too dark for my taste. It loses detail. Maybe a curves adjustment would help. great pose.</td>', 'too dark for my taste. It loses detail. Maybe a curves adjustment would help. great pose.', '2008-08-13 17:34:50.000000', NULL, 1),
(4886572, 709765, 29777, '<td valign="top">Not sure I like the lighting. It is a bit too pointed.</td>', 'Not sure I like the lighting. It is a bit too pointed.', '2008-08-13 17:40:23.000000', NULL, 1),
(4886574, 709959, 29777, '<td valign="top">freaky. It scared me.</td>', 'freaky. It scared me.', '2008-08-13 17:40:43.000000', NULL, 1),
(4886588, 710017, 29777, '<td valign="top">nice concept. The background is distracting because it is so bright. If you could tone down the green and enhance the yellow it might work better. This shot looks like it took a while to get right.</td>', 'nice concept. The background is distracting because it is so bright. If you could tone down the green and enhance the yellow it might work better. This shot looks like it took a while to get right.', '2008-08-13 17:47:25.000000', NULL, 1),
(4886593, 710210, 29777, '<td valign="top">DOF too shallow to see the gator eye in focus. Not sure how you got this shot. IT looks tricky.</td>', 'DOF too shallow to see the gator eye in focus. Not sure how you got this shot. IT looks tricky.', '2008-08-13 17:49:09.000000', NULL, 1),
(4886599, 710271, 29777, '<td valign="top">The shallow DOF does not add to the image IMO. I like the bubbles better in focus.</td>', 'The shallow DOF does not add to the image IMO. I like the bubbles better in focus.', '2008-08-13 17:51:12.000000', NULL, 1),
(4886602, 708164, 29777, '<td valign="top">too dark and not in focus</td>', 'too dark and not in focus', '2008-08-13 17:51:31.000000', NULL, 1),
(4886662, 710176, 29777, '<td valign="top">cool concept</td>', 'cool concept', '2008-08-13 18:15:52.000000', NULL, 1),
(4886702, 708875, 14369, '<td valign="top">little out of focus</td>', 'little out of focus', '2008-08-13 18:27:01.000000', NULL, 1),
(4886705, 708529, 12571, '<td valign="top">That cat is NOT happy. :)</td>', 'That cat is NOT happy. :)', '2008-08-13 18:28:12.000000', NULL, 1),
(4886733, 710176, 64610, '<td valign="top">I like this - good sense of humor.</td>', 'I like this - good sense of humor.', '2008-08-13 18:35:29.000000', NULL, 1),
(4886736, 708793, 64610, '<td valign="top">very cute, I would like to see more of the little boy''s face.</td>', 'very cute, I would like to see more of the little boy''s face.', '2008-08-13 18:36:25.000000', NULL, 1),
(4886738, 710190, 64610, '<td valign="top">lol - very cute!</td>', 'lol - very cute!', '2008-08-13 18:36:56.000000', NULL, 1),
(4886782, 710162, 47541, '<td valign="top">A bit of a 70''s feel with the colours - cool!</td>', 'A bit of a 70''s feel with the colours - cool!', '2008-08-13 18:53:08.000000', NULL, 1),
(4886784, 708024, 47541, '<td valign="top">I hate to ask but are you going for the brown?</td>', 'I hate to ask but are you going for the brown?', '2008-08-13 18:53:27.000000', NULL, 1),
(4886787, 710038, 47541, '<td valign="top">Well yes, they are a group of blue ducks but ???</td>', 'Well yes, they are a group of blue ducks but ???', '2008-08-13 18:53:51.000000', NULL, 1),
(4886788, 710256, 96477, '<td valign="top">I tried for 3 hours to get this same shot and never did get it.  Finally entered the woody contest instead.  Great job.</td>', 'I tried for 3 hours to get this same shot and never did get it.  Finally entered the woody contest instead.  Great job.', '2008-08-13 18:54:05.000000', NULL, 1),
