(4886793, 710289, 47541, '<td valign="top">I presume the idea was a duck in a pond?</td>', 'I presume the idea was a duck in a pond?', '2008-08-13 18:55:17.000000', NULL, 1),
(4886796, 708799, 47541, '<td valign="top">One of the better shots in this challenge</td>', 'One of the better shots in this challenge', '2008-08-13 18:55:33.000000', NULL, 1),
(4886797, 709503, 96477, '<td valign="top">Again?  I think this has been done at least once before.  It is a respectable rendition though.</td>', 'Again?  I think this has been done at least once before.  It is a respectable rendition though.', '2008-08-13 18:55:45.000000', NULL, 1),
(4886798, 709310, 47541, '<td valign="top">Poor poor ducky!  he does look unloved.  I find the sky a bit too dark though</td>', 'Poor poor ducky!  he does look unloved.  I find the sky a bit too dark though', '2008-08-13 18:56:03.000000', NULL, 1),
