(4886802, 710075, 96477, '<td valign="top">I love the ducks expression this is classic.</td>', 'I love the ducks expression this is classic.', '2008-08-13 18:56:44.000000', NULL, 1),
(4886803, 709865, 47541, '<td valign="top">Oh, poor ducky.  This makes me think of ducks in school where there is always a group of ducks that are leaving out someone :(</td>', 'Oh, poor ducky.  This makes me think of ducks in school where there is always a group of ducks that are leaving out someone :(', '2008-08-13 18:57:03.000000', NULL, 1),
