(4886806, 710205, 47541, '<td valign="top">Nice idea but whats with the quality?</td>', 'Nice idea but whats with the quality?', '2008-08-13 18:57:47.000000', NULL, 1),
(4886807, 710033, 47541, '<td valign="top">It is a ducky but it''s nothing more :(</td>', 'It is a ducky but it''s nothing more :(', '2008-08-13 18:58:01.000000', NULL, 1),
(4886808, 710195, 47541, '<td valign="top">Just a little less brightness would have helped this</td>', 'Just a little less brightness would have helped this', '2008-08-13 18:58:22.000000', NULL, 1),
(4886809, 710126, 47541, '<td valign="top">Nice reflection and colours</td>', 'Nice reflection and colours', '2008-08-13 18:58:35.000000', NULL, 1),
(4886810, 710073, 47541, '<td valign="top">yep, a nice shot of a duck</td>', 'yep, a nice shot of a duck', '2008-08-13 18:58:49.000000', NULL, 1),
(4886812, 709588, 47541, '<td valign="top">There seems to be a greenish tint to the ducks - is that their correct colour?</td>', 'There seems to be a greenish tint to the ducks - is that their correct colour?', '2008-08-13 18:59:16.000000', NULL, 1),
(4886815, 710122, 47541, '<td valign="top">These ducks are so small - it''s hard to get them in a scaled environment!  More ice?</td>', 'These ducks are so small - it''s hard to get them in a scaled environment!  More ice?', '2008-08-13 18:59:46.000000', NULL, 1),
(4886816, 708899, 47541, '<td valign="top">Nice shot, I think some more work could have gone into the title</td>', 'Nice shot, I think some more work could have gone into the title', '2008-08-13 19:00:10.000000', NULL, 1),
(4886818, 708528, 47541, '<td valign="top">Hmmm, it''s really just someone holding a duck isn''t it?  Is the Knuckle-Duck something real or a concept you''ve made up?</td>', 'Hmmm, it''s really just someone holding a duck isn''t it?  Is the Knuckle-Duck something real or a concept you''ve made up?', '2008-08-13 19:00:41.000000', NULL, 1),
(4886820, 709769, 47541, '<td valign="top">Without the title I wouldn''t have seen that there was water in the pram</td>', 'Without the title I wouldn''t have seen that there was water in the pram', '2008-08-13 19:01:02.000000', NULL, 1),
(4886822, 708905, 47541, '<td valign="top">Cool flames, I would like the duck to be lit a little more</td>', 'Cool flames, I would like the duck to be lit a little more', '2008-08-13 19:02:04.000000', NULL, 1),
(4886823, 710240, 47541, '<td valign="top">Needs something to make this more than just a shot of a rubber duck</td>', 'Needs something to make this more than just a shot of a rubber duck', '2008-08-13 19:02:33.000000', NULL, 1),
(4886825, 708529, 47541, '<td valign="top">I like it - great idea.  It would be even better if you could have got the duck facing the cat</td>', 'I like it - great idea.  It would be even better if you could have got the duck facing the cat', '2008-08-13 19:03:01.000000', NULL, 1),
(4886826, 709498, 47541, '<td valign="top">DOf is good but I''m not a fan of the negative space</td>', 'DOf is good but I''m not a fan of the negative space', '2008-08-13 19:03:34.000000', NULL, 1),
(4886827, 707962, 47541, '<td valign="top">What''s a peep?</td>', 'What''s a peep?', '2008-08-13 19:03:57.000000', NULL, 1),
(4886829, 710207, 47541, '<td valign="top">This needs something more to make it not be just another shot of a rubber duck.</td>', 'This needs something more to make it not be just another shot of a rubber duck.', '2008-08-13 19:04:29.000000', NULL, 1),
(4886831, 709883, 47541, '<td valign="top">Good idea but you suffer from their being antoher shot with that idea that comes across better</td>', 'Good idea but you suffer from their being antoher shot with that idea that comes across better', '2008-08-13 19:04:51.000000', NULL, 1),
